<?php
require_once __DIR__.'/../config.php'; require_admin(); $pdo=db();
$students=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='student'")->fetchColumn();
$online=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='student' AND status='active' AND last_seen_at >= DATE_SUB(NOW(), INTERVAL ".(int)ONLINE_WINDOW_SECONDS." SECOND)")->fetchColumn();
$disabled=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='student' AND status='disabled'")->fetchColumn();
$today=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='student' AND created_at >= CURDATE()")->fetchColumn();
$week=(int)$pdo->query("SELECT COUNT(DISTINCT user_id) FROM tool_usage WHERE used_at >= DATE_SUB(NOW(), INTERVAL 7 DAY)")->fetchColumn();
$month=(int)$pdo->query("SELECT COUNT(DISTINCT user_id) FROM tool_usage WHERE used_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)")->fetchColumn();
$toolRows=$pdo->query("SELECT tool_key,COUNT(*) uses_count FROM tool_usage WHERE used_at >= DATE_SUB(NOW(), INTERVAL 30 DAY) GROUP BY tool_key ORDER BY uses_count DESC LIMIT 8")->fetchAll();
$users=$pdo->query("SELECT id,name,email,status,last_seen_at,created_at,role FROM users WHERE role='student' ORDER BY created_at DESC LIMIT 100")->fetchAll();
$logs=$pdo->query("SELECT a.event_type,a.details,a.created_at,u.name,u.email FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 12")->fetchAll();
$days=$pdo->query("SELECT DATE(created_at) day,COUNT(*) total FROM users WHERE role='student' AND created_at >= DATE_SUB(CURDATE(), INTERVAL 6 DAY) GROUP BY DATE(created_at) ORDER BY day")->fetchAll();
$pageTitle='Admin dashboard'; require __DIR__.'/../includes/header.php'; ?>
<section class="page-heading"><span class="eyebrow">OWNER CONSOLE</span><h1>Admin <span>overview.</span></h1><p>Monitor account activity, growth, and which study tools students use.</p></section>
<section class="stats-grid admin-stats"><div class="stat-card"><span>TOTAL STUDENTS</span><strong><?= $students ?></strong><small>Registered student accounts</small></div><div class="stat-card"><span>ONLINE NOW</span><strong class="status-active">● <?= $online ?></strong><small>Heartbeat within 2 minutes</small></div><div class="stat-card"><span>NEW TODAY</span><strong><?= $today ?></strong><small>Registrations since midnight</small></div><div class="stat-card"><span>DISABLED</span><strong><?= $disabled ?></strong><small>Accounts currently disabled</small></div></section>
<section class="admin-chart-grid"><div class="panel"><div class="panel-head"><div><span class="eyebrow">ENGAGEMENT</span><h2>Active users</h2></div></div><div class="engagement-metrics"><div><strong><?= $week ?></strong><span>Unique users · 7 days</span></div><div><strong><?= $month ?></strong><span>Unique users · 30 days</span></div></div><p class="muted small">Based on recorded tool usage. Users who log in but don't open a tracked tool aren't included in this metric.</p></div><div class="panel"><div class="panel-head"><div><span class="eyebrow">TOOL ANALYTICS</span><h2>Most-used tools · 30 days</h2></div></div><?php if(!$toolRows): ?><p class="muted">No tool usage recorded yet.</p><?php else: $max=max(array_column($toolRows,'uses_count')); foreach($toolRows as $t): ?><div class="bar-row"><div><span><?= e(ucfirst($t['tool_key'])) ?></span><b><?= (int)$t['uses_count'] ?></b></div><div class="bar-track"><span style="width:<?= round(((int)$t['uses_count']/$max)*100) ?>%"></span></div></div><?php endforeach; endif; ?></div></section>
<section class="panel admin-users"><div class="panel-head"><div><span class="eyebrow">USER MANAGEMENT</span><h2>Student accounts</h2></div><span class="tool-count">LATEST 100</span></div><div class="table-search"><input id="user-search" placeholder="Search name or email…" aria-label="Search users"></div><div class="table-wrap"><table id="users-table"><thead><tr><th>Student</th><th>Status</th><th>Last active</th><th>Registered</th><th>Action</th></tr></thead><tbody><?php foreach($users as $u): $isOnline=$u['status']==='active' && $u['last_seen_at'] && strtotime($u['last_seen_at'])>=time()-ONLINE_WINDOW_SECONDS; ?><tr><td><b><?= e($u['name']) ?></b><small><?= e($u['email']) ?></small></td><td><?php if($u['status']==='disabled'): ?><span class="status-chip disabled">Disabled</span><?php elseif($isOnline): ?><span class="status-chip online">● Online</span><?php else: ?><span class="status-chip offline">● Offline</span><?php endif; ?></td><td><?= $u['last_seen_at']?e(date('M j, g:i a',strtotime($u['last_seen_at']))):'Never' ?></td><td><?= e(date('M j, Y',strtotime($u['created_at']))) ?></td><td><form method="post" action="user-action.php" onsubmit="return confirm('Change this account status?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><input type="hidden" name="action" value="<?= $u['status']==='active'?'disable':'enable' ?>"><button class="small-action" type="submit"><?= $u['status']==='active'?'Disable':'Enable' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><p class="muted small">For privacy and safety, account controls should only be used for legitimate moderation. This table displays up to 100 latest student accounts.</p></section>
<section class="panel"><div class="panel-head"><div><span class="eyebrow">AUDIT TRAIL</span><h2>Recent activity logs</h2></div></div><div class="activity-list"><?php if(!$logs): ?><p class="muted">No activity logged yet.</p><?php endif; foreach($logs as $l): ?><div class="activity-item"><span class="activity-dot"></span><div><b><?= e(ucfirst(str_replace('_',' ',$l['event_type']))) ?> · <?= e($l['name']??'Deleted account') ?></b><small><?= e($l['details']??'') ?> <?= $l['email']?'— '.e($l['email']):'' ?></small></div><time><?= e(date('M j, g:i a',strtotime($l['created_at']))) ?></time></div><?php endforeach; ?></div></section>
<script>document.getElementById('user-search').addEventListener('input',function(){const q=this.value.toLowerCase();document.querySelectorAll('#users-table tbody tr').forEach(r=>r.hidden=!r.innerText.toLowerCase().includes(q));});</script><?php require __DIR__.'/../includes/footer.php'; ?>
